function generalTimer(o){const n=(endDates[o]-Date.now())/1e3;var t=Math.floor(n/24/60/60),e=Math.floor(n-86400*t),r=Math.floor(e/3600),a=Math.floor(e-3600*r),s=Math.floor(a/60),c=n%60;function d(o){const n=Math.floor(o);return n<10?"0"+n:n}let u=parseInt(d(t));u>0?$("#countdown-days-"+o).html(u+"<small>d</small>"):$("#countdown-days-"+o).parent().remove(),$("#countdown-hours-"+o).html(d(r)),$("#countdown-mins-"+o).html(d(s)),$("#countdown-secs-"+o).html(d(c)),n<=0&&(clearInterval(countdownTimers[o]),$("#countdown-days-"+o).html("-"),$("#countdown-hours-"+o).html("--"),$("#countdown-mins-"+o).html("--"),$("#countdown-secs-"+o).html("--"),$("#countdown-days-"+o).parent().remove(),$("#countdown-hours-"+o).parent().remove(),$("#countdown-mins-"+o).parent().remove(),$("#countdown-secs-"+o).parent().remove(),$(".countdown-time-separators-"+o).remove(),$("#countdown-auction-ended-"+o).removeClass("d-none"))}